                            } else if !check_fn_signature(&f_orig.sig, &f_changed.sig) {

                                // Print out error information
                                println!("Disallowed changes found in an executable function's requires/ensures conditions");
                                println!("\tOriginal signature: {}", f_orig.sig.to_token_stream().to_string());
                                println!("\tChanged  signature: {}", f_changed.sig.to_token_stream().to_string());
                                return false;
                            } else {
                                idx_orig = idx_orig + 1;
                                idx_changed = idx_changed + 1;
                            }
                        },
                        _ => {
                            return false;
                        }
                    }}
                } else {
                    // non target function: exact match
                    if f_orig != f_changed {
                        if matches!(f_orig.sig.mode, Exec(_) | Default)
                            && matches!(f_changed.sig.mode, Exec(_) | Default)
                            && f_orig.sig.ident == f_changed.sig.ident
                        {
                            let mut normalized_orig = f_orig.clone();
                            normalized_orig.block = Box::new(normalize_atomic_with_ghost_block(&f_orig.block));
                            let mut normalized_changed = f_changed.clone();
                            normalized_changed.block = Box::new(normalize_atomic_with_ghost_block(&f_changed.block));
                            if normalized_orig == normalized_changed {
                                idx_orig = idx_orig + 1;
                                idx_changed = idx_changed + 1;
                                continue;
                            }
                        }
                        // if the changed item is a proof fn (but not axiom) or spec fn, skip this item, we will allow it to be added
                        match f_changed.sig.mode {
                            Spec(_) | SpecChecked(_) | Proof(_) => {
                                idx_changed = idx_changed + 1;
                            },
                            _ => {
                                println!("Disallowed addition of a new function: {}", mynewfun);
                                return false;
                            }
                        }
                    } else {
                        idx_orig = idx_orig + 1;
                        idx_changed = idx_changed + 1;
                    }
                }
            },
            (syn_verus::Item::Impl(i_orig), syn_verus::Item::Impl(i_changed)) => {
                // exact match for everything besides verifier attrs
                let mut orig_clone = i_orig.clone();
                orig_clone.items = Vec::new();
                orig_clone.attrs = remove_proof_attr(&orig_clone.attrs);
                let mut changed_clone = i_changed.clone();
                changed_clone.items = Vec::new();
                changed_clone.attrs = remove_proof_attr(&changed_clone.attrs);
                // check exact match, then check child items
                if orig_clone != changed_clone {
                    return false;
                } else if !check_impl_items(&i_orig.items[0..], &i_changed.items[0..]) {
                    println!("Disallowed changes made to impl block: {}", i_orig.self_ty.to_token_stream().to_string());
                    // println!("{:#?}", i_orig);
                    // println!("{:#?}", i_changed);
                    return false;
                }
                else {
                    // then advance to next item
                    idx_orig = idx_orig + 1;
                    idx_changed = idx_changed + 1;
                }
            },
            (syn_verus::Item::Trait(t_orig), syn_verus::Item::Trait(t_changed)) => {
                // exact match for everything besides verifier attrs
                let mut orig_clone = t_orig.clone();
                orig_clone.items = Vec::new();
                orig_clone.attrs = remove_proof_attr(&orig_clone.attrs);
                let mut changed_clone = t_changed.clone();
                changed_clone.items = Vec::new();
                changed_clone.attrs = remove_proof_attr(&changed_clone.attrs);
                // check exact match, then check child items
                if !(orig_clone == changed_clone && check_trait_items(&t_orig.items[0..], &t_changed.items[0..])) {
                    return false;
                } else {
                    // then advance to next item
                    idx_orig = idx_orig + 1;
                    idx_changed = idx_changed + 1;
                }
            },
            (_, syn_verus::Item::Use(_)) | (_, syn_verus::Item::Macro(_)) | (_, syn_verus::Item::BroadcastUse(_)) => {
                // check exact match
                if original != changed {
                    if let (syn_verus::Item::Macro(original_macro), syn_verus::Item::Macro(changed_macro)) = (original, changed) {
                        if tokenized_state_machine_change_is_safe(original_macro, changed_macro) {
                            idx_orig = idx_orig + 1;
                            idx_changed = idx_changed + 1;
                            continue;
                        }
                    }
                    // these items are allowed to be added. skip this item in changed file
                    idx_changed = idx_changed + 1;
                } else {
                    idx_orig = idx_orig + 1;
                    idx_changed = idx_changed + 1;
                }
            },
            (syn_verus::Item::Mod(m_orig), syn_verus::Item::Mod(m_changed)) => {
                if !mod_decl_is_equal(&m_orig, &m_changed) {
                    println!("Disallowed changes made to module declaration: {}", m_orig.ident.to_string());
                    return false;
                }

                match (&m_orig.content, &m_changed.content) {
                    (Some((orig_br, orig_items)), Some((changed_br, changed_items))) => {
                        if orig_br != changed_br {
                            println!("Disallowed changes made to module content braces: {}", m_orig.ident.to_string());
                            return false;
                        } else if !check_items(&orig_items[0..], &changed_items[0..]) {
                            return false;
                        } else {
                            idx_orig = idx_orig + 1;
                            idx_changed = idx_changed + 1;
                        }
                    },
                    (None, None) => {
                        idx_orig = idx_orig + 1;
                        idx_changed = idx_changed + 1;
                    },
                    _ => {
                        println!("Disallowed changes made to module content: {}", m_orig.ident.to_string());
                        return false;
                    }
                }

            },
            (_, _) => {
                if original != changed {
                    println!("{:#?}", changed);
                    println!("{:#?}", original);
                    println!("{}", changed.to_token_stream().to_string());
                    println!("{}", original.to_token_stream().to_string());
                    return false;
                } else {
                    idx_orig = idx_orig + 1;
                    idx_changed = idx_changed + 1;
                }
            }
        }
    }
    return idx_orig == original_items.len();
}

/*
Safety check rules:
- we can add new spec fns or proof fns
- we cannot change existing spec, proof, or exec fns -- EXCEPT the target function
- we cannot change the signature of the target function, except to add decreases, opens invariants, or prover clause
- we cannot change exec code in the body of the target function
- functions annotated with `#[inductive(...)]` are transition proof functions;
  their target body may be completed as proof code while their declaration is preserved
- in any existing exec function, we may change only the proof body of a
  well-formed `atomic_with_ghost!(... ghost binding => { ... })` invocation;
  its target, operation, and other clauses must remain unchanged
- the target function is identified by being a proof or exec fn whose body does not contain `unimplemented!()`.
    all other proof and exec fn will have a body with `unimplemented!()`
*/
pub fn check_allowed_additions_only(original_file: PathBuf, changed_file: PathBuf) -> Result<bool, Error> {
    let original = fload_file(&original_file)?;
    let changed = fload_file(&changed_file)?;
    let original_source = fs::read_to_string(&original_file).map_err(Error::ReadFile)?;
    let changed_source = fs::read_to_string(&changed_file).map_err(Error::ReadFile)?;

    let original_pure_file = remove_verus_macro(&original);
    let changed_pure_file = remove_verus_macro(&changed);

    if !check_items(&original_pure_file.items[0..], &changed_pure_file.items[0..]) {
        return Ok(false);
    }

    extract_verus_macro_with_context(&original, &original_file, &original_source).and_then(|original_verus_macros| {
        extract_verus_macro_with_context(&changed, &changed_file, &changed_source).and_then(|changed_verus_macros| {

            if original_verus_macros.len() != changed_verus_macros.len() {
                println!("Disallowed changes made to Verus macros in the original files.");
                return Ok(false);
            }

            // original_verus_macros.iter().for_each(|m| {
            //     println!("{}", fprint_file(&m, Formatter::VerusFmt))
            // });

            // changed_verus_macros.iter().for_each(|m| {
            //     println!("{}", fprint_file(&m, Formatter::VerusFmt))
            // });

            for i in 0..original_verus_macros.len() {
                if !check_items(&original_verus_macros[i].items[0..], &changed_verus_macros[i].items[0..]) {
                    println!("Disallowed changes made to Verus macros in the original files.");
                    return Ok(false);
                }
            }

            Ok(true)
        })
    })
}

use crate::{utils::*, DeghostMode};
use proc_macro2::{Delimiter, Group, TokenStream, TokenTree};
use quote::ToTokens;
use std::path::PathBuf;
use syn_verus::Token;
use syn_verus::TraitItemFn;
use syn_verus::parse_quote;
use syn_verus::visit_mut::VisitMut;

/// Remove only the proof block from a well-formed `atomic_with_ghost!` macro.
///
/// The macro's target, operation, optional `update`/`returning` clauses, and
/// ghost binding are retained.  Returning `None` for an unfamiliar shape is
/// intentional: callers must then compare the macro unchanged.
fn normalized_atomic_with_ghost_tokens(tokens: &TokenStream) -> Option<TokenStream> {
    let mut trees: Vec<TokenTree> = tokens.clone().into_iter().collect();
    let ghost_positions: Vec<usize> = trees
        .iter()
        .enumerate()
        .filter_map(|(index, tree)| match tree {
            TokenTree::Ident(ident) if ident == "ghost" => Some(index),
            _ => None,
        })
        .collect();

    if ghost_positions.len() != 1 {
        return None;
    }

    let ghost = ghost_positions[0];
    // The supported Verus grammar ends in: `ghost <identifier> => { ... }`.
    if ghost + 5 != trees.len()
        || !matches!(&trees[ghost + 1], TokenTree::Ident(_))
        || !matches!(&trees[ghost + 2], TokenTree::Punct(p) if p.as_char() == '=')
        || !matches!(&trees[ghost + 3], TokenTree::Punct(p) if p.as_char() == '>')
    {
        return None;
    }

    let body = match &trees[ghost + 4] {
        TokenTree::Group(group) if group.delimiter() == Delimiter::Brace => group,
        _ => return None,
    };
    let mut empty_body = Group::new(Delimiter::Brace, TokenStream::new());
    empty_body.set_span(body.span());
    trees[ghost + 4] = TokenTree::Group(empty_body);
    Some(trees.into_iter().collect())
}

/// Remove only the body of `proof { ... }` blocks in a
/// `try_open_atomic_update!` macro.
///
/// The macro contains both executable code (such as a physical CAS) and
/// ghost code that establishes the logical-atomic commit.  We preserve every
/// token except the contents of already-present proof blocks, so a proof
/// completion cannot change the linearization-point operation, its token
/// binding, or its commit expression.
fn normalized_try_open_atomic_update_tokens(tokens: &TokenStream) -> Option<TokenStream> {
    fn normalize_groups(tokens: TokenStream) -> (TokenStream, bool) {
        let mut trees: Vec<TokenTree> = tokens.into_iter().collect();
        let mut changed = false;
        let mut index = 0;

        while index < trees.len() {
            if matches!(&trees[index], TokenTree::Ident(ident) if ident == "proof") {
                if let Some(TokenTree::Group(group)) = trees.get(index + 1) {
                    if group.delimiter() == Delimiter::Brace {
                        let mut empty = Group::new(Delimiter::Brace, TokenStream::new());
                        empty.set_span(group.span());
                        trees[index + 1] = TokenTree::Group(empty);
                        changed = true;
                        index += 2;
                        continue;
                    }
                }
            }

            if let TokenTree::Group(group) = &trees[index] {
                let (stream, group_changed) = normalize_groups(group.stream());
                if group_changed {
                    let mut normalized = Group::new(group.delimiter(), stream);
                    normalized.set_span(group.span());
                    trees[index] = TokenTree::Group(normalized);
                    changed = true;
                }
            }
            index += 1;
        }

        (trees.into_iter().collect(), changed)
    }

    let (normalized, changed) = normalize_groups(tokens.clone());
    changed.then_some(normalized)
}

fn normalize_atomic_with_ghost_macro(mac: &mut syn_verus::Macro) {
    if mac.path.is_ident("atomic_with_ghost") {
        if let Some(tokens) = normalized_atomic_with_ghost_tokens(&mac.tokens) {
            mac.tokens = tokens;
        }
    } else if mac.path.is_ident("try_open_atomic_update") {
        if let Some(tokens) = normalized_try_open_atomic_update_tokens(&mac.tokens) {
            mac.tokens = tokens;
        }
    }
}

struct AtomicWithGhostNormalizer;

impl VisitMut for AtomicWithGhostNormalizer {
    fn visit_macro_mut(&mut self, mac: &mut syn_verus::Macro) {
        normalize_atomic_with_ghost_macro(mac);
    }
}

fn normalize_atomic_with_ghost_expr(expr: &syn_verus::Expr) -> syn_verus::Expr {
    let mut normalized = expr.clone();
    AtomicWithGhostNormalizer.visit_expr_mut(&mut normalized);
    normalized
}

/// Normalize supported atomic proof blocks without removing any other ghost
/// code. This is used for non-target executable functions, which remain
/// otherwise byte-for-byte equivalent at the syntax-tree level.
pub fn normalize_atomic_with_ghost_block(block: &syn_verus::Block) -> syn_verus::Block {
    let mut normalized = block.clone();
    AtomicWithGhostNormalizer.visit_block_mut(&mut normalized);
    normalized
}

fn remove_ghost_local(local: &syn_verus::Local, mode: &DeghostMode) -> Option<syn_verus::Local> {
    match local.ghost {
        Some(_) => None,
        None => {
            match local.tracked {
                Some(_) => None,
                None => {
                    local.init.clone().map_or_else(
                        || {
                            Some(syn_verus::Local {
                                attrs: local.attrs.clone(),
                                let_token: local.let_token.clone(),
                                tracked: None,
                                ghost: None,
                                pat: local.pat.clone(),
                                init: None,
                                semi_token: local.semi_token.clone()
                            })
                        },
                        |i| {
                            remove_ghost_expr(&i.expr, mode).map(|i_expr| {
                                syn_verus::Local {
                                    attrs: local.attrs.clone(),
                                    let_token: local.let_token.clone(),
                                    tracked: None,
                                    ghost: None,
                                    pat: local.pat.clone(),
                                    init: Some(syn_verus::LocalInit {
                                        eq_token: i.eq_token.clone(),
                                        expr: Box::new(i_expr),
                                        diverge: i.diverge.clone().map_or_else(
                                            || None,
                                            |d| remove_ghost_expr(&d.1, mode).map(|e|
                                                (d.0.clone(), Box::new(e))
                                            )
                                        )
                                    }),
                                    semi_token: local.semi_token.clone()
                                }
                            })
                        }
                    )
                }
            }
        },
    }
}

fn remove_ghost_expr(expr: &syn_verus::Expr, mode: &DeghostMode) -> Option<syn_verus::Expr> {
    //println!("{}\n", expr.to_token_stream().to_string());
    match expr {
        syn_verus::Expr::Block(b) => remove_ghost_block(&b.block, mode).map(|new_block| {
            syn_verus::Expr::Block(syn_verus::ExprBlock {
                attrs: b.attrs.clone(),
                label: b.label.clone(),
                block: syn_verus::Block {
                    brace_token: b.block.brace_token.clone(),
                    stmts: new_block.stmts,
                },
            })
        }),
        syn_verus::Expr::Call(c) => {
            let new_args: syn_verus::punctuated::Punctuated<syn_verus::Expr, Token![,]> = c
                .args
                .iter()
                .map(|arg| {
                    if let syn_verus::Expr::Closure(c) = arg {
                        remove_ghost_expr(&*c.body, mode).unwrap()
                    } else {
                        arg.clone()
                    }
                })
                .collect();

            Some(syn_verus::Expr::Call(syn_verus::ExprCall {
                attrs: c.attrs.clone(),
                func: c.func.clone(),
                paren_token: c.paren_token.clone(),
                args: new_args,
                atomically: c.atomically.clone(),
            }))
        }
        syn_verus::Expr::Closure(c) => remove_ghost_expr(&*c.body, mode).map(|new_body| {
            syn_verus::Expr::Closure(syn_verus::ExprClosure {
                attrs: c.attrs.clone(),
                asyncness: c.asyncness.clone(),
                movability: c.movability.clone(),
                capture: c.capture.clone(),
                or1_token: c.or1_token.clone(),
                inputs: c.inputs.clone(),
                or2_token: c.or2_token.clone(),
                output: c.output.clone(),
                requires: if mode.requires { c.requires.clone() } else { None },
                ensures: if mode.ensures { c.ensures.clone() } else { None },
                inner_attrs: c.inner_attrs.clone(),
                body: Box::new(new_body),
                constness: c.constness.clone(),
                lifetimes: c.lifetimes.clone(),
                options: c.options.clone(),
                proof_fn: None
            })
        }),
        syn_verus::Expr::While(w) => {
            /*
             * Fields to remove:
             * - invariant_except_break
             * - invariant
             * - invariant_ensures
             * - ensures
             * - decreases
             */
            remove_ghost_block(&w.body, mode).map(|new_body| {
                syn_verus::Expr::While(syn_verus::ExprWhile {
                    attrs: w.attrs.clone(),
                    label: w.label.clone(),
                    while_token: w.while_token.clone(),
                    cond: Box::new(normalize_atomic_with_ghost_expr(&w.cond)),
                    body: new_body,
                    invariant_except_break: None, // Removed
                    invariant: None,              // Removed
                    invariant_ensures: None,      // Removed
                    ensures: None,                // Removed
                    decreases: None,              // Removed
                })
            })
        }
        syn_verus::Expr::Loop(l) => remove_ghost_block(&l.body, mode).map(|new_body| {
            syn_verus::Expr::Loop(syn_verus::ExprLoop {
                attrs: l.attrs.clone(),
                label: l.label.clone(),
                loop_token: l.loop_token.clone(),
                body: new_body,
                invariant_except_break: None,
                invariant: None,
                invariant_ensures: None,
                ensures: None,
                decreases: None,
            })
        }),
        syn_verus::Expr::ForLoop(f) => {
            /*
             * Fields to remove:
             * - invariant
             * - decreases
             */
            remove_ghost_block(&f.body, mode).map(|new_body| {
                syn_verus::Expr::ForLoop(syn_verus::ExprForLoop {
                    attrs: f.attrs.clone(),
                    label: f.label.clone(),
                    for_token: f.for_token.clone(),
                    pat: f.pat.clone(),
                    in_token: f.in_token.clone(),
                    expr: Box::new(normalize_atomic_with_ghost_expr(&f.expr)),
                    body: new_body,
                    expr_name: f.expr_name.clone(),
                    invariant_except_break: None, // Removed
                    invariant: None, // Removed
                    ensures: None, // Removed
                    decreases: None, // Removed
                })
            })
        }
        syn_verus::Expr::Unary(u) => {
            match u.op {
                /*
                 * verus:
                 * Proof
                 * Forall
                 * Exists
                 * Choose
                 */
                syn_verus::UnOp::Proof(_)
                | syn_verus::UnOp::Forall(_)
                | syn_verus::UnOp::Exists(_)
                | syn_verus::UnOp::Choose(_) => None,
                _ => Some(expr.clone()),
            }
        }
        syn_verus::Expr::If(i) => {
            remove_ghost_block(&i.then_branch, mode).and_then(|new_then_branch| {
                if let Some((else_token, else_expr)) = i.else_branch.as_ref() {
                    remove_ghost_expr(&*else_expr, mode).map(|new_else_branch| {
                        syn_verus::Expr::If(syn_verus::ExprIf {
                            attrs: i.attrs.clone(),
                            if_token: i.if_token.clone(),
                            cond: Box::new(normalize_atomic_with_ghost_expr(&i.cond)),
                            then_branch: new_then_branch,
                            else_branch: Some((else_token.clone(), Box::new(new_else_branch))),
                        })
                    })
                } else {
                    Some(syn_verus::Expr::If(syn_verus::ExprIf {
                        attrs: i.attrs.clone(),
                        if_token: i.if_token.clone(),
                        cond: Box::new(normalize_atomic_with_ghost_expr(&i.cond)),
                        then_branch: new_then_branch,
                        else_branch: None,
                    }))
                }
            })
        }
        syn_verus::Expr::Match(m) => {
            let new_arms: Vec<syn_verus::Arm> = m
                .arms
                .iter()
                .filter_map(|arm| {
                    remove_ghost_expr(&*arm.body, mode).map_or_else(
                        || Some(syn_verus::Arm {
                            attrs: arm.attrs.clone(),
                            pat: arm.pat.clone(),
                            guard: arm.guard.clone(),
                            fat_arrow_token: arm.fat_arrow_token.clone(),
                            body: Box::new(syn_verus::Expr::Block( parse_quote! { {} })), // insert an empty block. removing the match arm entirely can cause an error
                            comma: arm.comma.clone(),
                        }),
                        |new_body| Some(syn_verus::Arm {
                            attrs: arm.attrs.clone(),
                            pat: arm.pat.clone(),
                            guard: arm.guard.clone(),
                            fat_arrow_token: arm.fat_arrow_token.clone(),
                            body: Box::new(new_body),
                            comma: arm.comma.clone(),
                        }))
                })
                .collect();

            Some(syn_verus::Expr::Match(syn_verus::ExprMatch {
                attrs: m.attrs.clone(),
                match_token: m.match_token.clone(),
                expr: m.expr.clone(),
                brace_token: m.brace_token.clone(),
                arms: new_arms,
            }))
        }
        // veurs:
        syn_verus::Expr::Assert(a) => {
            fn annotated_assert(a: &syn_verus::Assert) -> bool {
                a.attrs.iter().any(|attr| match &attr.meta {
                    syn_verus::Meta::List(l) => l.tokens.to_string() == "(llm_do_not_change)",
                    _ => false
                })
            }

            if mode.asserts || (mode.asserts_anno && annotated_assert(a)) {
                Some(expr.clone())
            } else {
                None
            }
        }
        syn_verus::Expr::Macro(m) => {
            let mut normalized = m.clone();
            normalize_atomic_with_ghost_macro(&mut normalized.mac);
            Some(syn_verus::Expr::Macro(normalized))
        }
        syn_verus::Expr::Assume(..)
        | syn_verus::Expr::AssertForall(..)
        | syn_verus::Expr::RevealHide(..)
        | syn_verus::Expr::View(..)
        | syn_verus::Expr::BigAnd(..)
        | syn_verus::Expr::BigOr(..)
        | syn_verus::Expr::Is(..)
        | syn_verus::Expr::IsNot(..)
        | syn_verus::Expr::Has(..)
        | syn_verus::Expr::HasNot(..)
        | syn_verus::Expr::Matches(..)
        | syn_verus::Expr::GetField(..) => None,
        _ => Some(expr.clone()),
    }
}

fn remove_ghost_stmt(stmt: &syn_verus::Stmt, mode: &DeghostMode) -> Option<syn_verus::Stmt> {
    match stmt {
        syn_verus::Stmt::Local(l) => remove_ghost_local(l, mode).map(syn_verus::Stmt::Local),
        syn_verus::Stmt::Item(i) => {
            // While we do have visit_item, I am not sure if we need to visit the item here
            // or just keep it as is.
            Some(syn_verus::Stmt::Item(i.clone()))
            // match visit_item(i) {
            //     Some(new_item) => Some(syn_verus::Stmt::Item(new_item)),
            //     None => None
            // }
        }
        syn_verus::Stmt::Expr(e, s) => remove_ghost_expr(e, mode).map(|e1| syn_verus::Stmt::Expr(e1, s.clone())),
        syn_verus::Stmt::Macro(e) => {
            let mut normalized = e.clone();
            normalize_atomic_with_ghost_macro(&mut normalized.mac);
            Some(syn_verus::Stmt::Macro(normalized))
        },
    }
}

pub fn remove_ghost_block(block: &syn_verus::Block, mode: &DeghostMode) -> Option<syn_verus::Block> {
    let new_stms: Vec<syn_verus::Stmt> =
        block.stmts.iter().filter_map(|stmt| remove_ghost_stmt(stmt, mode)).collect();

    if new_stms.is_empty() {
        return None;
    }

    Some(syn_verus::Block { brace_token: block.brace_token.clone(), stmts: new_stms })
}

pub fn remove_ghost_sig(
    sig: &syn_verus::Signature,
    mode: &DeghostMode,
) -> Option<syn_verus::Signature> {
    /*
     * Fields to remove:
     * - publish
     * - broadcast
     * - prover
     * - mode
     * - requires
     * - ensures
     * - recommends
     * - decreases
     * - invariants
     */
    if (!mode.spec
        && matches!(sig.mode, syn_verus::FnMode::Spec(_) | syn_verus::FnMode::SpecChecked(_)))
        || matches!(sig.mode, syn_verus::FnMode::Proof(_))
    {
        return None;
    }

    Some(syn_verus::Signature {
        publish: syn_verus::Publish::Default, // Removed
        constness: sig.constness.clone(),
        asyncness: sig.asyncness.clone(),
        unsafety: sig.unsafety.clone(),
        abi: sig.abi.clone(),
        broadcast: sig.broadcast.clone(), // Removed
        mode: sig.mode.clone(),           // Removed
        fn_token: sig.fn_token.clone(),
        ident: sig.ident.clone(),
        generics: sig.generics.clone(),
        paren_token: sig.paren_token.clone(),
        inputs: sig.inputs.clone(),
        variadic: sig.variadic.clone(),
        output: match &sig.output {
            syn_verus::ReturnType::Type(_, _, _, ty) => {
                syn_verus::ReturnType::Type(Default::default(), None, None, ty.clone())
            }
            syn_verus::ReturnType::Default => syn_verus::ReturnType::Default,
        },
        spec: syn_verus::SignatureSpec {
            prover: sig.spec.prover.clone(), // Removed
            atomic_spec: None,
            // TODO: This fix needs to be propagated to other places using `Specification`
            requires: sig
                .spec
                .requires
                .clone()
                .map(|mut new_req| {
                    if !new_req.exprs.exprs.empty_or_trailing() {
                        new_req.exprs.exprs.push_punct(Default::default());
                    }
                    new_req
                })
                .filter(|_| mode.requires), // Removed
            recommends: sig.spec.recommends.clone().map(|mut new_rec| {
                if !new_rec.exprs.exprs.empty_or_trailing() {
                    new_rec.exprs.exprs.push_punct(Default::default());
                }
                new_rec
            }), // Removed
            ensures: sig
                .spec
                .ensures
                .clone()
                .map(|mut new_ens| {
                    if !new_ens.exprs.exprs.empty_or_trailing() {
                        new_ens.exprs.exprs.push_punct(Default::default());
                    }
                    new_ens
                })
                .filter(|_| mode.ensures), // Removed
            decreases: sig
                .spec
                .decreases
                .clone()
                .map(|mut new_dec| {
                    if !new_dec.decreases.exprs.exprs.empty_or_trailing() {
                        new_dec.decreases.exprs.exprs.push_punct(Default::default());
                    }
                    new_dec
                })
                .filter(|_| mode.decreases), // Removed
            invariants: sig.spec.invariants.clone().filter(|_| mode.invariants), // Removed
            default_ensures: sig
                .spec
                .default_ensures
                .clone()
                .map(|mut new_ens| {
                    if !new_ens.exprs.exprs.empty_or_trailing() {
                        new_ens.exprs.exprs.push_punct(Default::default());
                    }
                    new_ens
                })
                .filter(|_| mode.ensures), // Removed
            returns: None,
            unwind: None,
            with: None
        }
    })
}

fn is_verifier_attr(attr: &syn_verus::Attribute) -> bool {
    attr.path().segments.len() > 0 && attr.path().segments[0].ident.to_string() == "verifier"
}

pub fn remove_verifier_attr(attr: &Vec<syn_verus::Attribute>) -> Vec<syn_verus::Attribute> {
    attr.iter().filter(|a| !is_verifier_attr(a)).map(|a| a.clone()).collect()
}

/*
 * Target Mode:
 *  Executable function: qualifiers cannot be modifified; executable part cannot be modified
 *  spec function: cannot be modified at all
 *  proof function: do not care at all
 * Non-Target Mode:
 *  Executable function: qualifiers can be modified; executable part cannot be modified
 *  spec function: do not care at all
 *  proof function: do not care at all
 */

fn remove_ghost_fn(func: &syn_verus::ItemFn, mode: &DeghostMode) -> Option<syn_verus::ItemFn> {
    remove_ghost_sig(&func.sig, mode).and_then(|new_sig| {
        if matches!(new_sig.mode, syn_verus::FnMode::Spec(_) | syn_verus::FnMode::SpecChecked(_)) {
            Some(func.clone())
        } else {
            remove_ghost_block(&(*func.block), mode).map(|new_block| {
                syn_verus::ItemFn {
                    attrs: remove_verifier_attr(&func.attrs),
                    vis: func.vis.clone(),
                    sig: new_sig,
                    block: Box::new(new_block), // Box the new block
                    semi_token: func.semi_token.clone(), // XXX: What is this?
                }
            })
        }
    })
}

fn remove_ghost_impl(i: &syn_verus::ItemImpl, mode: &DeghostMode) -> syn_verus::ItemImpl {
    syn_verus::ItemImpl {
        attrs: i.attrs.clone(),
        defaultness: i.defaultness.clone(),
        unsafety: i.unsafety.clone(),
        constness: i.constness.clone(),
        impl_token: i.impl_token.clone(),
        generics: i.generics.clone(),
        trait_: i.trait_.clone(),
        self_ty: i.self_ty.clone(),
        brace_token: i.brace_token.clone(),
        items: i
            .items
            .iter()
            .filter_map(|it| {
                if let syn_verus::ImplItem::Fn(func) = it {
                    remove_ghost_sig(&func.sig, mode).and_then(|new_sig| {
                        {
                            if matches!(
                                new_sig.mode,
                                syn_verus::FnMode::Spec(_) | syn_verus::FnMode::SpecChecked(_)
                            ) {
                                Some(func.clone())
                            } else {
                                remove_ghost_block(&func.block, mode).map(|new_block| {
                                    syn_verus::ImplItemFn {
                                        attrs: func.attrs.clone(),
                                        vis: func.vis.clone(),
                                        defaultness: func.defaultness.clone(),
                                        sig: new_sig,
                                        block: new_block,
                                        semi_token: func.semi_token.clone(), // XXX: What is this?
                                    }
                                })
                            }
                        }
                        .and_then(|new_method| Some(syn_verus::ImplItem::Fn(new_method)))
                    })
                } else {
                    Some(it.clone())
                }
            })
            .collect(),
    }
}

fn remove_ghost_item(item: &syn_verus::Item, mode: &DeghostMode) -> Option<syn_verus::Item> {
    match item {
        syn_verus::Item::Fn(f) => match remove_ghost_fn(f, mode) {
            Some(new_func) => Some(syn_verus::Item::Fn(new_func)),
            None => None,
        },
        syn_verus::Item::Impl(i) => Some(syn_verus::Item::Impl(remove_ghost_impl(i, mode))),
        syn_verus::Item::Trait(t) => Some(syn_verus::Item::Trait(syn_verus::ItemTrait {
            attrs: t.attrs.clone(),
            vis: t.vis.clone(),
            constness: t.constness.clone(),
            unsafety: t.unsafety.clone(),
            auto_token: t.auto_token.clone(),
            trait_token: t.trait_token.clone(),
            ident: t.ident.clone(),
            generics: t.generics.clone(),
            colon_token: t.colon_token.clone(),
            supertraits: t.supertraits.clone(),
            brace_token: t.brace_token.clone(),
            restriction: t.restriction.clone(),
            items: t
                .items
                .iter()
                .filter_map(|i| match i {
                    syn_verus::TraitItem::Fn(func) => {
                        Some(syn_verus::TraitItem::Fn(TraitItemFn {
                            attrs: func.attrs.clone(),
                            sig: remove_ghost_sig(&func.sig, mode)?,
                            default: func.default.as_ref().map(|b| {
                                remove_ghost_block(b, mode).unwrap_or_else(|| syn_verus::Block {
                                    brace_token: Default::default(),
                                    stmts: Vec::new(),
                                })
                            }),
                            semi_token: func.semi_token.clone(),
                        }))
                    }
                    _ => Some(i.clone()),
                })
                .collect::<Vec<syn_verus::TraitItem>>(),
        })),
        _ => Some(item.clone()), // syn_verus::Item::Macro(m) => visit_macro(m),
                                 // syn_verus::Item::Mod(m) => visit_mod(m),
                                 // syn_verus::Item::Use(u) => visit_use(u),
                                 // syn_verus::Item::Struct(s) => visit_struct(s),
                                 // syn_verus::Item::Enum(e) => visit_enum(e),
                                 // syn_verus::Item::Type(t) => visit_type(t),
                                 // syn_verus::Item::Const(c) => visit_const(c),
                                 // syn_verus::Item::Static(s) => visit_static(s),
                                 // syn_verus::Item::Union(u) => visit_union(u),
                                 // syn_verus::Item::TraitAlias(t) => visit_trait_alias(t),
                                 // syn_verus::Item::ExternCrate(e) => visit_extern_crate(e),
                                 // syn_verus::Item::ForeignMod(f) => visit_foreign_mod(f),
                                 // syn_verus::Item::Macro2(m) => visit_macro2(m),
                                 // syn_verus::Item::Verbatim(v) => visit_verbatim(v),
    }
}

pub fn remove_ghost_from_file(file: &syn_verus::File, mode: &DeghostMode) -> syn_verus::File {
    let mut new_items: Vec<syn_verus::Item> = Vec::new();

    for item in &file.items {
        if let Some(item) = remove_ghost_item(item, mode) {
            new_items.push(item);
        }
    }

    let new_file = syn_verus::File {
        shebang: file.shebang.clone(),
        attrs: file.attrs.clone(),
        items: new_items,
    };

    new_file
}

pub fn remove_verus_macro(file: &syn_verus::File) -> syn_verus::File {
    let mut new_items: Vec<syn_verus::Item> = Vec::new();

    for item in &file.items {
        if let syn_verus::Item::Macro(m) = item {
            if !is_verus_macro(&m.mac) {
                new_items.push(item.clone());
            }
        } else {
            new_items.push(item.clone());
        }
    }

    let new_file = syn_verus::File {
        shebang: file.shebang.clone(),
        attrs: file.attrs.clone(),
        items: new_items,
    };

    new_file
}

pub fn deghost_merge_files(file: &syn_verus::File, verus_files: Vec<syn_verus::File>) -> syn_verus::File {
    let mut new_items: Vec<syn_verus::Item> = Vec::new();

    for item in &file.items {
        new_items.push(item.clone());
    }

    for verus_file in verus_files {
        for item in &verus_file.items {
            new_items.push(item.clone());
        }
    }

    let new_file = syn_verus::File {
        shebang: file.shebang.clone(),
        attrs: file.attrs.clone(),
        items: new_items,
    };

    new_file
}

pub fn fextract_pure_rust(filepath: PathBuf, mode: &DeghostMode) -> Result<syn_verus::File, Error> {
    let orig_file = fload_file(&filepath)?;
    let pure_file = remove_verus_macro(&orig_file);

    extract_verus_macro(&orig_file).and_then(|verus_macros| {
        let mut verus_files: Vec<syn_verus::File> = Vec::new();
        for vm in verus_macros {
            let new_verus_file = remove_ghost_from_file(&vm, mode);

            let mut new_verus_ts = TokenStream::new();

            new_verus_file.to_tokens(&mut new_verus_ts);
            verus_files.push(new_verus_file);
        }

        //println!("{}", fprint_file(&merge_files(&pure_file, verus_files.clone()), VFormatter::VerusFmt));

        Ok(deghost_merge_files(&pure_file, verus_files))
    })
}

